// js/shared/spawns.js — spread spawn points for new players (ARCH §4.6). Pure ESM data + a picker.
// Points sit on a SIDEWALK of a real street (ROADS_DT way, not an elevated bridge way), on land, inside PLAY_RADIUS and
// ≥ 1 m outside every real building footprint. Generated by `node server/scripts/gen_spawns.mjs` and re-verified
// against the CURRENT terrain/map/building data by server/test/shared_spawns.test.js (fails if the city data moved).
// yaw faces along the street (0 = +Z, atan2(dir.x, dir.z) like main.js).
import { PLAY_RADIUS } from './constants.js';

export const SPAWNS = Object.freeze([
  { id: 'opera', name: 'Quảng trường Nhà hát lớn', x: -10.7, z: 75.6, yaw: 1.82 },
  { id: 'buudien', name: 'Bưu điện thành phố', x: -13.7, z: -699.2, yaw: -1.21 },
  { id: 'tambac', name: 'Hồ Tam Bạc', x: -909.6, z: 339.3, yaw: -1.37 },
  { id: 'chosat', name: 'Chợ Sắt', x: -1179.8, z: 150.6, yaw: -0.81 },
  { id: 'ga', name: 'Ga Hải Phòng', x: 577.6, z: 148.9, yaw: 2 },
  { id: 'lachtray', name: 'Phố Lạch Tray', x: 947.5, z: 1154.9, yaw: 0.41 },
  { id: 'chuahang', name: 'Chùa Hàng', x: -665.4, z: 1106.7, yaw: -3.09 },
  { id: 'nhatho', name: 'Nhà thờ lớn', x: -148.7, z: -350, yaw: 3.14 },
].map((s) => Object.freeze(s)));

export const SPAWN_JITTER_M = 2.5;   // along-street jitter so simultaneous joins do not stack on one point

// Pick the spawn with the fewest players nearby. `counts[i]` = current players near SPAWNS[i] (optional);
// ties are broken by `rand` (0..1). Returns {index, x, z, yaw, id, name} with a small jitter along the yaw direction.
export function pickSpawn(counts, rand = Math.random) {
  let best = -1, bestC = Infinity, ties = 0;
  for (let i = 0; i < SPAWNS.length; i++) {
    const c = counts ? counts[i] || 0 : 0;
    if (c < bestC) { bestC = c; best = i; ties = 1; }
    else if (c === bestC) { ties++; if (rand() * ties < 1) best = i; }
  }
  const s = SPAWNS[best];
  const j = (rand() * 2 - 1) * SPAWN_JITTER_M;
  return { index: best, id: s.id, name: s.name, x: s.x + Math.sin(s.yaw) * j, z: s.z + Math.cos(s.yaw) * j, yaw: s.yaw };
}

// Index of the spawn nearest to (x, z).
export function nearestSpawn(x, z) {
  let best = 0, bd = Infinity;
  for (let i = 0; i < SPAWNS.length; i++) {
    const d = (SPAWNS[i].x - x) ** 2 + (SPAWNS[i].z - z) ** 2;
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

export const SPAWN_MAX_R = PLAY_RADIUS - 20;
